import sqlite3
import os
import hashlib
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/data/app.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        password_hash TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_key = os.environ.get('ADMIN_API_KEY', 'default-key-change-me')
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, api_key) VALUES (?, ?, ?, ?)",
              ('admin', hashlib.sha256(b'admin').hexdigest(), 'admin', admin_key))
    db.commit()
    db.close()

def log_action(action, actor):
    db = get_db()
    db.execute("INSERT INTO audit_log (action, actor) VALUES (?, ?)", (action, actor))
    db.commit()

@app.before_request
def check_api_key():
    # Public endpoints don't need auth
    if request.endpoint in ('health', 'public_info'):
        return None
    key = request.headers.get('X-API-Key', '')
    if not key:
        return jsonify({"error": "missing api key"}), 401

@app.route('/health')
def health():
    return jsonify({"status": "ok"})

@app.route('/public_info')
def public_info():
    return jsonify({"version": "2.1.0", "env": os.environ.get('DEPLOY_ENV', 'unknown')})

@app.route('/api/users/search')
def search_users():
    """Search users by username pattern.
    The query parameter 'q' is used to filter usernames.
    """
    api_key = request.headers.get('X-API-Key', '')
    q = request.args.get('q', '')

    # Input validation: reject obvious SQL keywords
    blocked_words = ['DROP', 'DELETE', 'INSERT', 'UPDATE', 'ALTER', 'EXEC']
    for word in blocked_words:
        if word.lower() in q.lower():
            log_action(f"blocked_search: {q[:50]}", api_key[:8])
            return jsonify({"error": "invalid search term"}), 400

    # Length check
    if len(q) > 100:
        return jsonify({"error": "query too long"}), 400

    # Build query - using string formatting for LIKE pattern matching
    # NOTE: parameterized queries don't work well with LIKE wildcards in some drivers
    query = f"SELECT id, username, role FROM users WHERE username LIKE '%{q}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        users = [{"id": r["id"], "username": r["username"], "role": r["role"]} for r in results]
        log_action(f"search: {q[:50]}", api_key[:8])
        return jsonify({"results": users})
    except Exception as e:
        return jsonify({"error": "search failed", "detail": str(e)}), 500

@app.route('/api/users/<int:user_id>')
def get_user(user_id):
    db = get_db()
    user = db.execute("SELECT id, username, role FROM users WHERE id = ?", (user_id,)).fetchone()
    if user:
        return jsonify({"id": user["id"], "username": user["username"], "role": user["role"]})
    return jsonify({"error": "not found"}), 404

@app.route('/api/admin/keys', methods=['POST'])
def rotate_key():
    api_key = request.headers.get('X-API-Key', '')
    db = get_db()
    user = db.execute("SELECT * FROM users WHERE api_key = ?", (api_key,)).fetchone()
    if not user or user["role"] != 'admin':
        return jsonify({"error": "forbidden"}), 403
    new_key = hashlib.sha256(os.urandom(32)).hexdigest()
    db.execute("UPDATE users SET api_key = ? WHERE id = ?", (new_key, user["id"]))
    db.commit()
    log_action("key_rotation", user["username"])
    return jsonify({"new_key": new_key})

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080, debug=False)
